contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking inputs: recipient and amount
    function run(address to, uint256 value) public payable {
        require(true);

        // record observable state before
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balSenderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        bool frozenSenderBefore = c.frozenAccount(address(this)); if (__ESBMC_reverted()) return;
        bool frozenToBefore = c.frozenAccount(to); if (__ESBMC_reverted()) return;

        // perform the transfer and record whether it reverted
        bool reverted;
        bool res = c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = !res; // transfer returns true on success, but treat false as revert-like
        }

        // read after-state
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balSenderAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;
        bool frozenSenderAfter = c.frozenAccount(address(this)); if (__ESBMC_reverted()) return;
        bool frozenToAfter = c.frozenAccount(to); if (__ESBMC_reverted()) return;

        // General rule:
        // If the call did not revert, totalSupply is preserved and balances change by exactly value
        // from sender to recipient. If it reverted, totalSupply and balances are unchanged.
        assert(
            (
                reverted &&
                totalAfter == totalBefore &&
                balSenderAfter == balSenderBefore &&
                balToAfter == balToBefore &&
                frozenSenderAfter == frozenSenderBefore &&
                frozenToAfter == frozenToBefore
            ) || (
                !reverted &&
                totalAfter == totalBefore &&
                balSenderBefore >= value &&
                balSenderAfter + value == balSenderBefore &&
                balToAfter == balToBefore + value &&
                frozenSenderAfter == frozenSenderBefore &&
                frozenToAfter == frozenToBefore
            )
        );
    }

    receive() external payable {}
}

